/* =====================================================================================================
 * DMF0082 GET_MAIN_DATA 교체 · 00_PRECHECK_CLOUD — 교체 전 점검 (조회 전용)
 * 마커 [E20261104-DMF0082ONEQUERY] · 생성 2026-11-09 14:03:13 (사내 ZIOUI1) · 실행 계정 = SCM_MGR · 파일 전체 F5 · 값 입력 없음
 * 교체 = PKG_DMF0082 의 P_DMF0082_GET_MAIN_DATA 구간 ← PKG_DMF0082_1104 의 같은 구간 (이 DB 의 USER_SOURCE 끼리 · 나머지 프로시저 무변경)
 * ===================================================================================================== */
SET DEFINE OFF
SET SERVEROUTPUT ON SIZE UNLIMITED

-- G0 접속
SELECT 'G0' CHK, SYS_CONTEXT('USERENV','DB_NAME') DB_NAME, USER CUR_USER, TO_CHAR(SYSDATE,'YYYY-MM-DD HH24:MI:SS') NOW_TIME FROM DUAL;
-- G1 객체 상태 — 기대: PKG_DMF0082 · PKG_DMF0082_1104 PACKAGE/BODY 모두 VALID (PKG_DMF0082_1104 는 앞 패키지 DMF0082_1104_CLOUD_20261109 의 20 으로 만든 것)
SELECT 'G1' CHK, OBJECT_NAME, OBJECT_TYPE, STATUS, TO_CHAR(LAST_DDL_TIME,'YYYY-MM-DD HH24:MI:SS') LAST_DDL FROM USER_OBJECTS WHERE OBJECT_NAME IN ('PKG_DMF0082','PKG_DMF0082_1104') ORDER BY 1, 2;
-- G2 구간 경계 — 기대: 4행 모두 N = 1
SELECT 'G2' CHK, 'PKG_DMF0082' PKG, 'START' EDGE, COUNT(*) N, MIN(LINE) LINE_NO FROM USER_SOURCE WHERE NAME='PKG_DMF0082' AND TYPE='PACKAGE BODY' AND REGEXP_LIKE(TEXT, '^\s*PROCEDURE\s+P_DMF0082_GET_MAIN_DATA\s*(\(|$)')
UNION ALL SELECT 'G2', 'PKG_DMF0082', 'END', COUNT(*), MIN(LINE) FROM USER_SOURCE WHERE NAME='PKG_DMF0082' AND TYPE='PACKAGE BODY' AND REGEXP_LIKE(TEXT, '^\s*PROCEDURE\s+P_DMF0082_POPUP_GET_FUTUREPRICE_INFO(\s|\(|$)')
UNION ALL SELECT 'G2', 'PKG_DMF0082_1104', 'START', COUNT(*), MIN(LINE) FROM USER_SOURCE WHERE NAME='PKG_DMF0082_1104' AND TYPE='PACKAGE BODY' AND REGEXP_LIKE(TEXT, '^\s*PROCEDURE\s+P_DMF0082_GET_MAIN_DATA\s*(\(|$)')
UNION ALL SELECT 'G2', 'PKG_DMF0082_1104', 'END', COUNT(*), MIN(LINE) FROM USER_SOURCE WHERE NAME='PKG_DMF0082_1104' AND TYPE='PACKAGE BODY' AND REGEXP_LIKE(TEXT, '^\s*PROCEDURE\s+P_DMF0082_POPUP_GET_FUTUREPRICE_INFO(\s|\(|$)');
-- G3 PKG_DMF0082_1104 의 GET_MAIN_DATA 구간이 사내 검증본(apply #26)과 같은지 — 기대 SAME (사내 지문 줄 16294 · 길이 922025 · 해시합 35449467448126)
SELECT 'G3' CHK, X.N, X.L, X.H, CASE WHEN X.N = 16294 AND X.L = 922025 AND X.H = 35449467448126 THEN 'SAME'
            WHEN X.N = 16294 AND X.L = 922025 THEN 'SAME? (줄·길이 같음 · 해시만 다름)' ELSE 'DIFF — 중단 · 회신' END JUDGE
  FROM (WITH R AS (SELECT (SELECT MIN(LINE) FROM USER_SOURCE WHERE NAME='PKG_DMF0082_1104' AND TYPE='PACKAGE BODY' AND REGEXP_LIKE(TEXT, '^\s*PROCEDURE\s+P_DMF0082_GET_MAIN_DATA\s*(\(|$)')) L1,
                  (SELECT MIN(LINE) FROM USER_SOURCE WHERE NAME='PKG_DMF0082_1104' AND TYPE='PACKAGE BODY' AND REGEXP_LIKE(TEXT, '^\s*PROCEDURE\s+P_DMF0082_POPUP_GET_FUTUREPRICE_INFO(\s|\(|$)')) L2 FROM DUAL)
SELECT COUNT(*) N, NVL(SUM(LENGTH(RTRIM(TEXT, ' ' || CHR(9) || CHR(10) || CHR(13)))), 0) L, NVL(SUM(ORA_HASH(RTRIM(TEXT, ' ' || CHR(9) || CHR(10) || CHR(13)))), 0) H FROM USER_SOURCE S, R
 WHERE S.NAME='PKG_DMF0082_1104' AND S.TYPE='PACKAGE BODY' AND S.LINE >= R.L1 AND S.LINE < R.L2 AND RTRIM(TEXT, ' ' || CHR(9) || CHR(10) || CHR(13)) IS NOT NULL) X;
-- G4 PKG_DMF0082 현재 GET_MAIN_DATA 구간 — 참고: 사내 원본(교체 전) 지문 줄 5285 · 길이 323720 · 해시합 11513597021521
--    ALREADY = 이미 교체됨(20 은 SKIP) · ORIG_SAME_AS_CORP = 사내 원본과 같음 · ORIG_DIFF = 클라우드 원본이 사내와 다른 세대(교체는 그대로 가능 — 이 구간 전체가 1104 로 바뀜)
SELECT 'G4' CHK, X.N, X.L, X.H,
       CASE WHEN X.N = 16294 AND X.L = 922025 AND X.H = 35449467448126 THEN 'ALREADY'
            WHEN X.N = 5285 AND X.L = 323720 AND X.H = 11513597021521 THEN 'ORIG_SAME_AS_CORP' ELSE 'ORIG_DIFF' END JUDGE
  FROM (WITH R AS (SELECT (SELECT MIN(LINE) FROM USER_SOURCE WHERE NAME='PKG_DMF0082' AND TYPE='PACKAGE BODY' AND REGEXP_LIKE(TEXT, '^\s*PROCEDURE\s+P_DMF0082_GET_MAIN_DATA\s*(\(|$)')) L1,
                  (SELECT MIN(LINE) FROM USER_SOURCE WHERE NAME='PKG_DMF0082' AND TYPE='PACKAGE BODY' AND REGEXP_LIKE(TEXT, '^\s*PROCEDURE\s+P_DMF0082_POPUP_GET_FUTUREPRICE_INFO(\s|\(|$)')) L2 FROM DUAL)
SELECT COUNT(*) N, NVL(SUM(LENGTH(RTRIM(TEXT, ' ' || CHR(9) || CHR(10) || CHR(13)))), 0) L, NVL(SUM(ORA_HASH(RTRIM(TEXT, ' ' || CHR(9) || CHR(10) || CHR(13)))), 0) H FROM USER_SOURCE S, R
 WHERE S.NAME='PKG_DMF0082' AND S.TYPE='PACKAGE BODY' AND S.LINE >= R.L1 AND S.LINE < R.L2 AND RTRIM(TEXT, ' ' || CHR(9) || CHR(10) || CHR(13)) IS NOT NULL) X;
-- G5 PKG_DMF0082 실행 중 세션 (V$SESSION 권한 없으면 안내만 출력) — 기대 0. 0 이 아니면 화면 조회가 끝난 뒤 20 실행
DECLARE
    n PLS_INTEGER;
BEGIN
    EXECUTE IMMEDIATE q'[SELECT COUNT(*) FROM V$SESSION S WHERE S.STATUS = 'ACTIVE' AND S.PLSQL_ENTRY_OBJECT_ID IN (SELECT OBJECT_ID FROM USER_OBJECTS WHERE OBJECT_NAME = 'PKG_DMF0082' AND OBJECT_TYPE = 'PACKAGE')]' INTO n;
    DBMS_OUTPUT.PUT_LINE('G5 PKG_DMF0082 실행 중 세션 ' || n || CASE WHEN n = 0 THEN ' (기대)' ELSE ' — 끝난 뒤 20 실행' END);
EXCEPTION WHEN OTHERS THEN
    DBMS_OUTPUT.PUT_LINE('G5 V$SESSION 조회 권한 없음 — DMF0082 조회·저장이 돌지 않는 시간에 20 실행 (' || SQLCODE || ')');
END;
/
